```rust
// elevenlabs.rs
use reqwest;

pub struct ElevenLabs {
    api_key: String,
}

impl ElevenLabs {
    pub fn new(api_key: String) -> Self {
        ElevenLabs { api_key }
    }

    pub async fn generate_speech_synthesis(&self, text: &str) -> Result<String, reqwest::Error> {
        let url = format!("https://api.elevenlabs.io/v1/speech_synthesis?text={}&key={}", text, self.api_key);
        let response = reqwest::get(url).await?;
        let audio_file = response.text().await?;
        Ok(audio_file)
    }
}
```
